//! Register map: byte offsets on BAR0, reset values, field shifts and masks.
//!
//! Everything here is generated by bindgen from `host/include/omni_regs.h`
//! (itself generated from `gateware/regmap/map_v0.ml`), except the
//! [`proposed`] constants, which the map does not have yet.

#![allow(non_upper_case_globals, dead_code)]

include!(concat!(env!("OUT_DIR"), "/omni_regs.rs"));

pub mod proposed;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn constants_match_the_map() {
        assert_eq!(OMNI_ID, 0x0000);
        assert_eq!(OMNI_ID_RESET, 0x4F4D_4E49);
        assert_eq!(OMNI_SCRATCH, 0x0008);
        assert_eq!(OMNI_SRC_CTL, 0x1000);
        assert_eq!(OMNI_SRC_RATE_RESET, 0x1_0000);
        assert_eq!(OMNI_SNK_BEATS_HI, 0x200C);
        assert_eq!(OMNI_RING_CLEAR, 0x300C);
        assert_eq!(OMNI_VERSION_MAJOR_MASK, 0xFFFF_0000);
        assert_eq!(OMNI_STATUS_RING_OVERFLOW_SHIFT, 3);
    }

    #[test]
    fn constants_are_u32() {
        // bindgen picks the type from the literal; offsets must stay u32 so
        // `Transport::read32(OMNI_*)` needs no casts.
        let _: u32 = OMNI_SRC_BEATS_LO;
        let _: u32 = OMNI_SNK_CTL_MODE_MASK;
    }
}
